import 'dart:io';

import 'package:crypto/crypto.dart';
import 'package:world_mystery/core/assets/season_pack_manifest.dart';

/// The generated file the app is built with.
const generatedPath = 'lib/core/assets/season_pack_manifests.g.dart';

/// The season the app ships whole (`SeasonPack.london.folder`); every other
/// season's pictures are downloaded (season packs), but its cover.
const bundledSeasonFolder = 'season_01_london';

/// Whether [path] (an asset file or `…/` folder) ships inside the app:
/// anything but a downloaded season's pictures, which come from the bucket;
/// a season's `cover/` (shown on the World Map and in the archives before any
/// download) and London ship.
bool shipsInApp(String path) => switch (path.split('/')) {
  _ when appOnlySeasonFiles.contains(path) => true,
  ['assets', 'seasons', final folder, final sub, ...] => folder == bundledSeasonFolder || sub == 'cover',
  _ => true,
};

/// A downloaded season's pictures that ship in the app (listed one by one in
/// `pubspec.yaml`) and are kept out of its pack: added after the pack went
/// to the bucket.
// shortcut: Seoul Case 11 M2's papers and Case 02 M1's room finds (2026-11-07, no R2 upload yet); move them into the pack at its next upload.
const appOnlySeasonFiles = {
  'assets/seasons/season_05_seoul/cases/case_11/c11_copy_list.webp',
  'assets/seasons/season_05_seoul/cases/case_11/c11_drop_card.webp',
  'assets/seasons/season_05_seoul/cases/case_02/find_bucket_room.webp',
  'assets/seasons/season_05_seoul/cases/case_02/find_straw_room.webp',
  'assets/seasons/season_05_seoul/cases/case_02/find_note_room.webp',
};

/// Every season pack: each file under `assets/seasons/<folder>/` on disk,
/// measured and hashed. Read from disk, not `pubspec.yaml`: the downloaded
/// seasons' pictures are no longer in the app.
List<SeasonPackManifest> measureSeasonPacks({String root = '.'}) {
  final byFolder = <String, List<SeasonPackFile>>{};
  for (final e in Directory('$root/assets/seasons').listSync(recursive: true).whereType<File>()) {
    final path = e.path.substring(root.length + 1).replaceAll(r'\', '/');
    if (appOnlySeasonFiles.contains(path)) continue;
    final bytes = e.readAsBytesSync();
    byFolder.putIfAbsent(path.split('/')[2], () => []).add(SeasonPackFile(path, bytes.length, sha256.convert(bytes).toString()));
  }
  return [
    for (final folder in byFolder.keys.toList()..sort())
      SeasonPackManifest(
        folder: folder,
        version: SeasonPackManifest.versionOf(byFolder[folder]!),
        files: byFolder[folder]!..sort((a, b) => a.path.compareTo(b.path)),
      ),
  ];
}

/// [packs] as the Dart source of [generatedPath].
String renderManifests(List<SeasonPackManifest> packs) {
  final out = StringBuffer()
    ..writeln('// GENERATED by `dart run tool/season_packs/build_manifest.dart`. Do not edit.')
    ..writeln('// The season packs the app was built with: every file, its size and SHA-256.')
    ..writeln()
    ..writeln("import 'season_pack_manifest.dart';")
    ..writeln()
    ..writeln('/// By `SeasonPack.folder`.')
    ..writeln('const seasonPackManifests = <String, SeasonPackManifest>{');
  for (final p in packs) {
    out
      ..writeln("  '${p.folder}': SeasonPackManifest(")
      ..writeln("    folder: '${p.folder}',")
      ..writeln("    version: '${p.version}',")
      ..writeln('    files: [');
    for (final f in p.files) {
      out.writeln("      SeasonPackFile('${f.path}', ${f.bytes}, '${f.sha256}'),");
    }
    out
      ..writeln('    ],')
      ..writeln('  ),');
  }
  out.writeln('};');
  return out.toString();
}
